    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names = sorted(packages, reverse=(name_order == "descending"))
    best_key = None
    best_versions = None

    def active_dependencies(row):
        return [dep for dep in row.get("deps", [])
                if not dep.get("feature") or dep["feature"] in features]

    def acyclic(versions, rows):
        edges = {name: [dep["name"] for dep in active_dependencies(rows[name])]
                 for name in versions}
        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        return all(visit(name) for name in edges)

    def search(versions, selected_rows, constraints):
        nonlocal best_key, best_versions
        for name, bounds_list in constraints.items():
            if name in versions and any(not low <= versions[name] <= high
                                        for low, high in bounds_list):
                return

        unresolved = [name for name in constraints if name not in versions]
        if not unresolved:
            if not acyclic(versions, selected_rows):
                return
            key = tuple(versions.get(name, -1) for name in names)
            if (best_key is None or
                    (key < best_key if preference == "minimum" else key > best_key)):
                best_key = key
                best_versions = dict(versions)
            return

        name = min(unresolved)
        bounds_list = constraints[name]
        rows = [row for row in packages[name]
                if all(low <= row["version"] <= high for low, high in bounds_list)
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        rows.sort(key=lambda row: row["version"], reverse=(preference == "maximum"))
        for row in rows:
            next_versions = dict(versions)
            next_versions[name] = row["version"]
            next_rows = dict(selected_rows)
            next_rows[name] = row
            next_constraints = {pkg: list(ranges) for pkg, ranges in constraints.items()}
            for dep in active_dependencies(row):
                next_constraints.setdefault(dep["name"], []).append(
                    (dep["min"], dep["max"]))
            search(next_versions, next_rows, next_constraints)

    initial = {name: [(bounds[0], bounds[1])]
               for name, bounds in data["roots"].items()}
    search({}, {}, initial)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


